/**
 * 通用「产品族」页面模板 —— `/industries/`、`/features/`、`/use-cases/`、`/compare/`
 *
 * 由 `gatsby-node.js` 的 `createPages` 从 `src/data/{industries,features,useCases,compare}.js`
 * 生成。四族结构完全相同，差异集中在 `src/data/families.js`（族元数据）+ 各数据文件
 * （每页的 sections / faq）。**改版式只需改这一个文件**，不会出现「有一族忘了改」。
 *
 * 🔴 **为什么用 context 里的 `family` 键分发，而不是建 4 个模板文件**：
 *    四个模板的 JSX 会逐字相同，唯一差别是「从哪个数组取数据、面包屑指向哪」——
 *    那就是典型的「同一规范值两处实现」，必然漂移。这里按 key 查表，只有一个实现。
 *
 * 🔴 **红线**（真源 `whaleal-messaging/docs/BSP角色与免责边界-对外文案稿.md` §6）：
 *    不得宣称「一个 API 对接三通道」、不得宣称模板渲染/模板管理、
 *    不得把 SMS-only 的能力（自动故障切换 / 按号码限速 / 分段计费 / STOP 关键词写入抑制）
 *    写成三通道通用，也不得把回执写成三通道全供应商都有（按供应商，见 `integrations.js`）。
 *    数据文件里的每一页都要能指到代码/线上事实，不得凭印象写。
 *
 * 🔴 `softwareApp={false}` —— 本族讲平台，不是 Whaleal Cart 那个 Shopify 应用。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { FAMILIES } from '../data/families';
import { INDUSTRIES } from '../data/industries';
import { FEATURES } from '../data/features';
import { USE_CASES } from '../data/useCases';
import { COMPARISONS } from '../data/compare';
import { GUIDES } from '../data/guides';
import { MESSAGING_CONSOLE_URL } from '../constants/brand';
import '../styles/marketing.css';

/** family key → 数据数组。新增一族时这里与 `gatsby-node.js` 各加一行。 */
const FAMILY_DATA = {
  industries: INDUSTRIES,
  features: FEATURES,
  'use-cases': USE_CASES,
  compare: COMPARISONS,
};

export default function FamilyPage({ pageContext }) {
  const { family: familyKey, page } = pageContext;
  const family = FAMILIES[familyKey];
  const all = FAMILY_DATA[familyKey] || [];

  const { name, h1, eyebrow, metaTitle, metaDescription, lede, sections = [], faq = [], guides = [] } = page;

  // 相关 guide 从同一份 GUIDES 数据取标题，避免在数据里重复维护一遍标题（会漂移）
  const relatedGuides = (guides || []).map((slug) => GUIDES.find((g) => g.slug === slug)).filter(Boolean);

  // 同族其余页 —— 内链是这类落地页能否被爬到的关键，别省
  const siblings = all.filter((p) => p.slug !== page.slug);

  const detailPath = `${family.indexPath}${page.slug}/`;

  return (
    <Layout>
      <SEO
        title={metaTitle}
        description={metaDescription}
        pathname={detailPath}
        softwareApp={false}
        /* 结构化数据与正文用同一份数组/同一层级，见 family-page.js 文件头「一处实现」的判据 */
        faqs={faq}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: family.crumbLabel, path: family.indexPath },
          { name, path: detailPath },
        ]}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{eyebrow || family.eyebrow}</span>
          <h1>{h1}</h1>
          <p className="mk-lead">{lede}</p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONSOLE_URL}>
              Open the console
            </a>
            <Link className="mk-btn mk-btn-secondary" to={family.indexPath}>
              {family.ctaSecondaryLabel}
            </Link>
          </div>
        </header>

        {sections.map((section) => (
          <section className="mk-section" key={section.h}>
            <h2>{section.h}</h2>
            {(section.p || []).map((para, i) => (
              <p className="mk-section-lead" key={i}>
                {para}
              </p>
            ))}
            {section.bullets && (
              <ul className="mk-list">
                {section.bullets.map((b) => (
                  <li key={b}>{b}</li>
                ))}
              </ul>
            )}
          </section>
        ))}

        {faq.length > 0 && (
          <section className="mk-section">
            <h2>Questions this usually raises</h2>
            <dl className="mk-faq">
              {faq.map((item) => (
                <div className="mk-faq-item" key={item.q}>
                  <dt>{item.q}</dt>
                  <dd>{item.a}</dd>
                </div>
              ))}
            </dl>
          </section>
        )}

        {(relatedGuides.length > 0 || siblings.length > 0) && (
          <section className="mk-section">
            <h2>Keep reading</h2>
            <div className="mk-grid">
              {relatedGuides.map((g) => (
                <article className="mk-card" key={g.slug}>
                  <span className="mk-card-tag">{g.readMinutes} min</span>
                  <h3>{g.title}</h3>
                  <p>{g.excerpt}</p>
                  <Link className="mk-card-link" to={`/guides/${g.slug}/`}>
                    Read the guide &rarr;
                  </Link>
                </article>
              ))}
              {siblings.map((s) => (
                <article className="mk-card" key={s.slug}>
                  <span className="mk-card-tag">{family.crumbLabel}</span>
                  <h3>{s.name}</h3>
                  <p>{s.lede}</p>
                  <Link className="mk-card-link" to={`${family.indexPath}${s.slug}/`}>
                    Open &rarr;
                  </Link>
                </article>
              ))}
            </div>
          </section>
        )}

        <div className="mk-scope">
          <strong>Scope.</strong> {page.scope || family.scope}
        </div>
      </div>
    </Layout>
  );
}
